pm.test("Status response 200 OK - Login Berhasil", function () {
    pm.response.to.have.status(200);
});

pm.test("Token Bearer diekstrak dan disimpan otomatis ke variabel", function () {
    var jsonData = pm.response.json();
    pm.expect(jsonData.success).to.be.true;
    pm.expect(jsonData.data).to.be.an("object");
    pm.expect(jsonData.data.token).to.be.a("string");

    var token = jsonData.data.token;
    var user = jsonData.data.user || {};
    var role = user.role || "";

    // Simpan ke variabel umum untuk API yang membutuhkan bearer token
    pm.collectionVariables.set("bearer_token", token);
    pm.collectionVariables.set("token", token);
    if (pm.environment) {
        pm.environment.set("bearer_token", token);
        pm.environment.set("token", token);
    }

    // Simpan ke variabel spesifik peran (RBAC)
    var roleVarMap = {
        "admin": "admin_token",
        "doctor": "doctor_token",
        "nurse": "nurse_token",
        "registration": "reg_token",
        "pharmacist": "pharma_token",
        "pharmacy": "pharma_token",
        "lab": "lab_token",
        "cashier": "cashier_token"
    };

    if (role && roleVarMap[role]) {
        var roleVarName = roleVarMap[role];
        pm.collectionVariables.set(roleVarName, token);
        if (pm.environment) {
            pm.environment.set(roleVarName, token);
        }
        console.log("[Auth Script] " + roleVarName + " disetel untuk peran: " + role);
    }

    console.log("[Auth Script] Token Bearer otomatis aktif: " + token);
});
